<?php
/** Student's own booking history and pending-request cancellation. */
declare(strict_types=1);
require __DIR__ . '/includes/booking.php';
$pdo=booking_db(); $student=booking_student($pdo);
$s=$pdo->prepare("SELECT b.booking_id,b.bk_date AS requested_at,rd.room_label,p.title AS property_title,rs.slot_no AS slot_number,CASE WHEN a.decision='rejected' THEN 'rejected' WHEN a.occupancy_status='moved_out' THEN 'completed' WHEN a.occupancy_status='occupied' THEN 'active' WHEN b.bk_status='cancelled' THEN 'cancelled' WHEN b.bk_status='confirmed' THEN 'accepted' ELSE 'pending' END AS status FROM bookings b JOIN room_slots rs ON rs.slot_id=b.slot_id JOIN rooms r ON r.room_id=rs.room_id JOIN properties p ON p.property_id=r.property_id LEFT JOIN room_landlord_details rd ON rd.room_id=r.room_id LEFT JOIN booking_landlord_actions a ON a.booking_id=b.booking_id WHERE b.student_id=? ORDER BY b.bk_date DESC LIMIT 100");
$s->execute([(int)$student['student_id']]); $bookings=$s->fetchAll(PDO::FETCH_ASSOC);
$notice=booking_notice_take();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Bookings | BoardNest</title><link rel="stylesheet" href="assets/student_booking.css"></head><body><header class="student-header"><div class="student-nav"><a class="student-brand" href="search.php">Board<span>Nest</span></a><nav aria-label="Student navigation"><a href="search.php">Find rooms</a><a href="bookings.php" aria-current="page">My bookings</a><a href="../../logout.php">Sign out</a></nav></div></header><main class="student-main"><p class="kicker">YOUR REQUESTS</p><h1>My bookings</h1><p>Booking status changes when the landlord accepts, rejects, checks in or checks out.</p>
<?php if($notice):?><div class="notice" role="status"><?=booking_e($notice)?></div><?php endif;?>
<div class="booking-list"><?php foreach($bookings as $b):?><article class="booking-item"><div><strong><?=booking_e($b['property_title'])?></strong><p><?=booking_e($b['room_label'] ?: 'Room')?> · Slot <?=(int)$b['slot_number']?> · <?=booking_e($b['requested_at'])?></p><span class="availability"><?=booking_e(booking_status_label($b['status']))?></span></div><?php if($b['status']==='pending'):?><form action="actions/cancel_booking.php" method="post"><input type="hidden" name="_csrf" value="<?=booking_e(booking_csrf())?>"><input type="hidden" name="booking_id" value="<?=(int)$b['booking_id']?>"><button class="btn secondary" type="submit">Cancel request</button></form><?php endif;?></article><?php endforeach;?><?php if(!$bookings):?><p class="empty">You have no bookings yet. <a href="search.php">Explore boarding rooms</a>.</p><?php endif;?></div></main></body></html>
